// src/schemas.ts

import { z } from 'zod'

export const StepSchema = z.object({
  name: z.string(),
  status: z.string(),
  detail: z.string()
})

export const StepListSchema = z.array(StepSchema)

/**
 * Schema for quota usage information.
 * Validates the quota_info object returned in 402 responses.
 */
export const QuotaInfoSchema = z.object({
  used: z.number(),
  limit: z.number(),
  resource: z.string()
})

/**
 * Schema for structured error details returned by the API.
 * Used to validate error responses and extract actionable information.
 */
export const StructuredErrorDetailSchema = z.object({
  code: z.string().optional(),
  description: z.string().optional(),
  organization_id: z.string().optional(),
  assignment_id: z.string().optional(),
  expires_at: z.string().optional(),
  period_start: z.string().optional(),
  period_end: z.string().optional(),
  status: z.string().optional(),
  steps: StepListSchema.optional(),
  owner: z.string().optional(),
  owner_type: z.string().optional(),
  quota_info: QuotaInfoSchema.optional(),
  // Flat-code 402 plan/quota denial fields returned by POST /api-product/submit
  // (e.g. code=QUOTA_EXCEEDED with usage numbers). Surfaced so the usage block
  // renders and the numbers are not dropped.
  quota_used: z.number().optional(),
  quota_limit: z.number().optional(),
  quota_remaining: z.number().optional(),
  // Future ENTITLEMENT_DENIED envelope fields. reason_code maps to a canonical
  // plan/quota code and remediation provides ready-to-display guidance.
  reason_code: z.string().optional(),
  remediation: z.string().optional()
})

/**
 * Schema for the structured 403 error detail returned by the backend when the
 * AppSecAI GitHub App cannot push to the target repository. The locked service
 * contract guarantees these fields.
 */
export const RepoAccessErrorDetailSchema = z.object({
  code: z.string(),
  message: z.string(),
  owner: z.string().optional(),
  repo: z.string().optional(),
  reason: z.string().optional(),
  source: z.string().optional()
})

/**
 * Schema for run summary data from Medusa/Product API.
 * Nullable fields (issue_titles, issue_titles_by_url) are accepted when null from API
 * to maintain parser resilience to Medusa contract variations.
 * Canonical precedence: issue_titles_by_url (preferred) -> issue_titles (legacy).
 * Consumers should check both fields in precedence order; rendering is URL-only if both are absent/null.
 */
export const RunSummarySchema = z.object({
  total_vulnerabilities: z.number().default(0),
  true_positives: z.number().default(0),
  false_positives: z.number().default(0),
  needs_manual_review_count: z.number().default(0),
  handled_error_count: z.number().default(0),
  has_handled_errors: z.boolean().default(false),
  cwe_breakdown: z.record(z.string(), z.number()).default({}),
  severity_breakdown: z.record(z.string(), z.number()).default({}),
  remediation_success: z.number().default(0),
  remediation_failed: z.number().default(0),
  pr_urls: z.array(z.string()).default([]),
  pr_titles: z.record(z.string(), z.string()).optional(),
  pr_count: z.number().default(0),
  customer_visible_pr_count: z.number().optional(),
  issue_urls: z.array(z.string()).default([]),
  issue_titles: z.record(z.string(), z.string()).nullable().optional(),
  issue_titles_by_url: z.record(z.string(), z.string()).nullable().optional(),
  issue_count: z.number().default(0),
  skipped_count: z.number().default(0),
  issues_validation_warning: z.number().optional(),
  issues_multistep_cwe: z.number().optional(),
  dedup_skipped_count: z.number().default(0),
  validation_failure_count: z.number().default(0),
  scope_validation_failure_count: z.number().optional(),
  remediation_with_warnings: z.number().default(0),
  internal_non_pushed_attempts: z.number().optional(),
  internal_non_pushed_findings: z.number().optional(),
  vendor_excluded_count: z.number().optional(),
  vendor_exclusion_count: z.number().optional(),
  manual_exclusion_count: z.number().optional(),
  triaged_false_positive_count: z.number().optional(),
  scanner_correlated_duplicate_count: z.number().optional(),
  correlated_duplicate_count: z.number().optional(),
  remediation_validation_failed_count: z.number().optional(),
  dropped_from_pr_count: z.number().optional(),
  remediation_unit_failure_count: z.number().optional(),
  push_failed_count: z.number().optional(),
  github_push_failure_count: z.number().optional(),
  not_attempted_count: z.number().optional(),
  outcome_breakdown: z.record(z.string(), z.number()).optional(),
  push_outcome_breakdown: z.record(z.string(), z.number()).optional()
})

/**
 * Valid values for context_updated field.
 * - true: Context was successfully updated
 * - false: Context was not requested or not updated
 * - 'rate-limited': Context update was requested but rate limited
 */
export const ContextUpdatedSchema = z.union([
  z.boolean(),
  z.literal('rate-limited')
])

export const RunResponseSchema = z.object({
  message: z.string(),
  description: z.string().nullish(),
  steps: StepListSchema,
  run_id: z.string().nullable(),
  organization_id: z.string().optional(),
  summary: RunSummarySchema.nullable().optional(),
  context_updated: ContextUpdatedSchema.optional()
})

export const SolverResultSchema = z.object({
  count: z.number(),
  extras: z.record(z.string(), z.any())
})

export const SolverResultsSchema = z.object({
  description: z.string().nullish(), // API returns null when not set
  find: SolverResultSchema.nullable(),
  triage: SolverResultSchema.nullable(),
  remediate: SolverResultSchema.nullable(),
  validate: SolverResultSchema.nullable(),
  push: SolverResultSchema.nullable()
})

/**
 * Valid status values for ProcessStatus.
 * Kept in sync with ProcessStatusValue type in types.ts.
 */
export const ProcessStatusValueSchema = z.enum([
  'not_started',
  'initiated',
  'in_progress',
  'completed',
  'failed'
])

/**
 * Schema for ProcessStatus.
 * Note: Uses lenient string type for status to remain forward-compatible
 * if the API adds new status values. The ProcessStatusValue type in types.ts
 * provides compile-time type safety for known values.
 */
export const ProcessStatusSchema = z.object({
  status: z.string().default('not_started'),
  started_at: z.string().nullish(), // API returns null, not undefined
  completed_at: z.string().nullish(), // API returns null, not undefined
  progress_percentage: z.number().default(0),
  error_message: z.string().nullish(), // API returns null, not undefined
  total_items: z.number().default(0),
  processed_items: z.number().default(0),
  success_count: z.number().default(0), // Successfully processed items (includes warnings)
  customer_visible_pr_count: z.number().optional(), // Customer-visible PRs created for push status
  error_count: z.number().default(0), // Actual processing exceptions
  dispatched_expected_count: z.number().default(0),
  dispatched_task_ids: z.array(z.string()).default([]),
  dispatched_callback_task_id: z.string().nullish(),
  dispatched_chord_group_ids: z.array(z.string()).default([]),
  dispatch_queue_name: z.string().nullish(),
  dispatch_recorded_at: z.string().nullish(),
  false_positive_count: z.number().default(0), // Items triaged as false positives (triage only)
  needs_manual_review_count: z.number().default(0), // Items routed to manual review (triage only)
  handled_error_count: z.number().default(0), // Handled errors routed to manual review (triage only)
  self_validation_warning_count: z.number().default(0), // Issues created (validation warnings - security passed, other checks failed)
  self_validation_failure_count: z.number().default(0), // Skipped (security not resolved)
  scope_validation_failure_count: z.number().default(0), // Deterministic scope validation failures preventing PR creation
  additional_context_required_count: z.number().default(0) // PRs with 'Additional Context Required' prefix
})

const ProcessActivityPartitionSchema = z
  .object({
    partition_id: z.string().optional(),
    label: z.string().optional(),
    language: z.string().optional(),
    status: z.string().optional(),
    processed_items: z.number().optional(),
    total_items: z.number().optional(),
    progress_percentage: z.number().optional(),
    completed_at: z.string().nullish(),
    terminal_reason: z.string().nullish()
  })
  .loose()

const ProcessActivitySchema = z
  .object({
    activity_id: z.string().optional(),
    label: z.string().optional(),
    status: z.string().default('not_started'),
    progress_percentage: z.number().optional(),
    processed_items: z.number().optional(),
    total_items: z.number().optional(),
    started_at: z.string().nullish(),
    completed_at: z.string().nullish(),
    terminal_reason: z.string().nullish(),
    error_message: z.string().nullish(),
    elapsed_ms: z.number().nullish(),
    budget_ms: z.number().nullish(),
    eta_ms: z.number().nullish(),
    eta_evidence: z.string().nullish(),
    partitions: z.array(ProcessActivityPartitionSchema).optional()
  })
  .loose()

const ProcessActivitiesSchema = z.union([
  z.record(z.string(), ProcessActivitySchema),
  z.array(ProcessActivitySchema)
])

export const RunProcessTrackingSchema = z
  .object({
    find_status: ProcessStatusSchema.optional(),
    triage_status: ProcessStatusSchema.optional(),
    remediate_status: ProcessStatusSchema.optional(),
    validate_status: ProcessStatusSchema.optional(),
    push_status: ProcessStatusSchema.optional(),
    remediation_validation_loop_status: ProcessStatusSchema.optional(),
    grouping_status: ProcessStatusSchema.optional(),
    group_remediate_status: ProcessStatusSchema.optional(),
    group_validate_status: ProcessStatusSchema.optional(),
    overall_status: ProcessStatusSchema.optional(),
    activities: ProcessActivitiesSchema.nullable().optional()
  })
  .loose()

export const ResponseStatusSchema = z.object({
  message: z.string(),
  description: z.string().nullable().optional(),
  run_status: z.string().nullable().optional(),
  // Machine-readable reason for non-terminal run states (e.g. why a run is
  // paused). Product may send either `status_reason` or `pause_reason`; both
  // are accepted so a paused run validates without surfacing a schema error.
  status_reason: z.string().nullable().optional(),
  pause_reason: z.string().nullable().optional(),
  dashboard_url: z.string().nullable().optional(),
  results: SolverResultsSchema.nullable(),
  process_tracking: RunProcessTrackingSchema.nullable().optional(),
  summary: RunSummarySchema.nullable().optional()
})

/**
 * Schema for quota-related error details (HTTP 429).
 * Validates the structured error response from the API.
 */
export const QuotaErrorDetailSchema = z.object({
  error: z.string().optional(),
  message: z.string().optional(),
  quota_used: z.number().optional(),
  quota_limit: z.number().optional(),
  period_start: z.string().optional(),
  period_end: z.string().optional()
})
